/* From Uiverse.io by Javierrocadev - Tags: youtube, card, video, cardhover , card hover, music player */
.__UIV_SCOPE__ .card {
  width: 260px;
  height: 170px;
  background-color: #ffb3b3;
  border-radius: 15px;
  border: 1px solid rgb(156, 151, 151);
  position: relative;
  transition: all .3s ease;
}

.__UIV_SCOPE__ .card__icons {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  padding-right: 10px;
  padding-top: 10px;
  gap: 10px;
  opacity: 0;
  transition: all .3s ease;
  cursor: pointer;
}

.__UIV_SCOPE__ .card__time {
  position: absolute;
  right: 10px;
  bottom: 10px;
  display: flex;
  justify-content: center;
  align-items: center;
  font-size: 1em;
  font-weight: lighter;
  border-radius: 5px;
  text-align: center;
  padding: 2px 8px;
  color: whitesmoke;
  background-color: rgb(77, 67, 67);
}

.__UIV_SCOPE__ .svg-icon {
  background-color: rgb(77, 67, 67);
  fill: #ece6e6;
  width: 35px;
  height: 35px;
  border-radius: 5px;
  padding: 2px;
  transition: all .5s ease-in-out;
}

.__UIV_SCOPE__ .card:hover {
  opacity: 0.8;
  animation: video 5s ease;
}

.__UIV_SCOPE__ .card:hover .card__icons {
  opacity: 1;
}
